from functools import wraps


class GoToState(object):

    @staticmethod
    def decorator(state):
        def inner(decorated):
            @wraps(decorated)
            def wrapper(*args, **kwargs):
                args[0].device.goto_state(state=state)
                result = decorated(*args, **kwargs)
                return result

            return wrapper

        return inner

    @staticmethod
    def epcsim():
        return GoToState.decorator(state='EPCSIM')

    @staticmethod
    def rtg():
        return GoToState.decorator(state='RTG')

    @staticmethod
    def emssim():
        return GoToState.decorator(state='EMSSIM')
